import{_ as a}from"./chunks/CreateCollaborateTree.IsNo73MB.js";import{_ as o,c as t,a2 as r,o as l}from"./chunks/framework.BQmytedh.js";const i="/assets/CreateCollaborateTab.1nub0Hsj.png",s="/assets/CreateShareDialog.Dc4rtmW6.png",f=JSON.parse('{"title":"Collaborate Feature  (Available on next version)","description":"","frontmatter":{},"headers":[],"relativePath":"doc/guides/usage/collaborate-feature.md","filePath":"doc/guides/usage/collaborate-feature.md"}'),n={name:"doc/guides/usage/collaborate-feature.md"};function c(h,e,d,u,p,g){return l(),t("div",null,e[0]||(e[0]=[r('<h1 id="collaborate-feature-available-on-next-version" tabindex="-1">Collaborate Feature <small>(Available on next version)</small> <a class="header-anchor" href="#collaborate-feature-available-on-next-version" aria-label="Permalink to &quot;Collaborate Feature  &lt;small&gt;(Available on next version)&lt;/small&gt;&quot;">​</a></h1><p>The Collaborate feature in ioChem-BD Create enables seamless teamwork on computational chemistry research projects. Share your projects with colleagues, manage access permissions, and track all collaboration activities in real-time.</p><p><img src="'+i+'" alt="Collaborate tab in Create module"></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Collaborate transforms how research teams work together by providing:</p><ul><li><strong>Flexible permission control</strong> - Define exactly what each collaborator can do with your shared projects</li><li><strong>Complete transparency</strong> - Track every action with detailed collaboration messages</li><li><strong>Effortless teamwork</strong> - Work simultaneously on the same projects without version conflicts</li></ul><h2 id="accessing-the-collaborate-tab" tabindex="-1">Accessing the Collaborate Tab <a class="header-anchor" href="#accessing-the-collaborate-tab" aria-label="Permalink to &quot;Accessing the Collaborate Tab&quot;">​</a></h2><p>To access shared projects, click on the <strong>Collaborate</strong> tab in the main navigation frame. This tab displays all projects that other users have shared with your group, organized by research group and owner.</p><p><img src="'+a+'" alt="Collaborate tree structure"></p><p>The Collaborate tree is organized hierarchically:</p><ul><li><strong>Research Groups</strong> - Top-level organization (e.g., &quot;Computational Chemistry Lab&quot;)</li><li><strong>Owners</strong> - Individual users who have shared projects with you</li><li><strong>Shared Projects</strong> - Projects available for collaboration</li><li><strong>Calculations</strong> - Individual calculations within shared projects</li></ul><h2 id="sharing-your-projects" tabindex="-1">Sharing Your Projects <a class="header-anchor" href="#sharing-your-projects" aria-label="Permalink to &quot;Sharing Your Projects&quot;">​</a></h2><p>To share one of your projects with collaborators:</p><ol><li>Navigate to your project in the <strong>My workspace</strong> tab</li><li>Select the project you want to share</li><li>Click the <strong>Share</strong> button in the context menu or item details</li><li>Choose collaborator user groups from the list</li><li>Assign appropriate permissions for each user group</li><li>Click <strong>Save</strong> to activate sharing</li></ol><p><img src="'+s+'" alt="Share project dialog"></p><h2 id="permission-levels" tabindex="-1">Permission Levels <a class="header-anchor" href="#permission-levels" aria-label="Permalink to &quot;Permission Levels&quot;">​</a></h2><p>When sharing a project, you can assign different permission levels to control what collaborators can do:</p><h3 id="read" tabindex="-1">READ <a class="header-anchor" href="#read" aria-label="Permalink to &quot;READ&quot;">​</a></h3><p>Collaborators with READ permission can:</p><ul><li>View project structure and calculations</li><li>Download calculation files</li><li>View 3D structures and results</li><li>Generate reports</li></ul><p>They <strong>cannot</strong>:</p><ul><li>Create, modify, or delete projects or calculations</li><li>Change project metadata</li><li>Publish to Browse module</li></ul><h3 id="write" tabindex="-1">WRITE <a class="header-anchor" href="#write" aria-label="Permalink to &quot;WRITE&quot;">​</a></h3><p>Collaborators with WRITE permission can do everything READ users can, plus:</p><ul><li>Create new subprojects and calculations</li><li>Upload new calculations</li><li>Modify project and calculation metadata</li></ul><p>They <strong>cannot</strong>:</p><ul><li>Delete the shared project itself</li><li>Publish to Browse module</li></ul><h3 id="full-access" tabindex="-1">FULL ACCESS <a class="header-anchor" href="#full-access" aria-label="Permalink to &quot;FULL ACCESS&quot;">​</a></h3><p>Collaborators with FULL ACCESS permission have full control:</p><ul><li>All WRITE access capabilities</li><li>Delete any element, <strong>excluding</strong> the shared project</li></ul><p>They <strong>cannot</strong>:</p><ul><li>Delete the shared project itself</li><li>Publish to Browse module</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Be careful when granting FULL ACCESS, as these users have complete control over your shared project.</p></div><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>Published projects and collections cannot be modified or removed, regardless of permission level. Once a project has been published to the Browse module, it becomes read-only for all users including the owner.</p></div><h2 id="working-with-shared-projects" tabindex="-1">Working with Shared Projects <a class="header-anchor" href="#working-with-shared-projects" aria-label="Permalink to &quot;Working with Shared Projects&quot;">​</a></h2><p>Once a project is shared with you, it appears in your Collaborate tab. You can work with shared projects similarly to your own projects:</p><h3 id="viewing-shared-content" tabindex="-1">Viewing Shared Content <a class="header-anchor" href="#viewing-shared-content" aria-label="Permalink to &quot;Viewing Shared Content&quot;">​</a></h3><ol><li>Navigate to the <strong>Collaborate</strong> tab</li><li>Expand the research group and owner to see shared projects</li><li>Click on any project or calculation to view its details</li></ol><p>The <strong>Item Actions</strong> and <strong>Item Details</strong> frames will display the selected element&#39;s information, just as they do for your own projects.</p><h3 id="adding-content-to-shared-projects" tabindex="-1">Adding Content to Shared Projects <a class="header-anchor" href="#adding-content-to-shared-projects" aria-label="Permalink to &quot;Adding Content to Shared Projects&quot;">​</a></h3><p>If you have WRITE or FULL ACCESS permissions:</p><ol><li>Select the shared project where you want to add content</li><li>Use the upload interface to add new calculations</li><li>Or create subprojects using the <strong>Create project</strong> button in Item Details</li></ol><p>All content you add will be visible to other collaborators immediately.</p><h3 id="modifying-shared-content" tabindex="-1">Modifying Shared Content <a class="header-anchor" href="#modifying-shared-content" aria-label="Permalink to &quot;Modifying Shared Content&quot;">​</a></h3><p>Depending on your permissions, you can modify shared content:</p><ol><li>Select the project or calculation you want to modify</li><li>Edit fields in the <strong>Item Details</strong> frame</li><li>Click <strong>Modify</strong> to save your changes</li></ol>',46)]))}const w=o(n,[["render",c]]);export{f as __pageData,w as default};
